CACHED_STATUSES = {"HIT", "REVALIDATED", "STALE", "UPDATING"}
_URL_PATH_SAFE = "/:@!$&'()*+,;=-._~%[]|"
_URL_QUERY_SAFE = "/?:@!$&'()*+,;=%-._~[]|{}^`"


